    """Return True if the card number is valid per the Luhn algorithm.

    The input is a string. Single spaces between digits are allowed and
    ignored. Returns False if, after removing spaces, there are fewer than
    two characters or any character is not a digit 0-9.
    """
    if not isinstance(number, str):
        return False

    # Remove spaces, but only single spaces between digits are allowed.
    # Validate structure before stripping.
    if "  " in number or number.startswith(" ") or number.endswith(" "):
        return False

    digits = number.replace(" ", "")

    if len(digits) < 2:
        return False

    if not digits.isdigit():
        return False

    total = 0
    for i, ch in enumerate(reversed(digits)):
        d = ord(ch) - ord("0")
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d

    return total % 10 == 0
